#!/usr/bin/env bash
# ck-code SessionStart hook.
#   (1) Reload skills so experts/guides generated by /ck-code:team become
#       invocable in the same session — no restart required.
#   (2) Inject a one-line workflow summary from STORIES_INDEX.md when present.
#
# Best-effort by design: this must NEVER fail or block session startup, so it
# avoids `set -e` and swallows every probe error. Output is a single JSON line.

index=$(ls tasks/*/STORIES_INDEX.md 2>/dev/null | head -1)

if [ -n "$index" ] && [ -f "$index" ]; then
  todo=$(grep -cE '\| *TODO *\|' "$index" 2>/dev/null); todo=${todo:-0}
  ip=$(grep -cE '\| *IN PROGRESS *\|' "$index" 2>/dev/null); ip=${ip:-0}
  done=$(grep -cE '\| *DONE *\|' "$index" 2>/dev/null); done=${done:-0}
  ctx="ck-code project detected ($index): $todo TODO, $ip IN PROGRESS, $done DONE. Run /ck-code:start for the recommended next step."
  printf '{"hookSpecificOutput":{"hookEventName":"SessionStart","reloadSkills":true,"additionalContext":"%s"}}\n' "$ctx"
else
  printf '{"hookSpecificOutput":{"hookEventName":"SessionStart","reloadSkills":true}}\n'
fi
